begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('55555555-5555-4555-8555-555555555555','trash-alice@example.test'),
 ('66666666-6666-4666-8666-666666666666','trash-bob@example.test');
set local role anon;
select throws_ok($$select public.list_trashed_idea_projects()$$,'42501',null,'Anonymous Trash denied');
select throws_ok($$select public.trash_idea_project(null,'{}','trash-test-key-0001')$$,'42501',null,'Anonymous delete denied');
select throws_ok($$select public.restore_idea_project(null,'{}','trash-test-key-0001')$$,'42501',null,'Anonymous restore denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated"}',true);
select set_config('test.source',public.create_idea_project('{"title":"Keep me","brief":"Saved idea","referenceText":"Saved notes","targetDurationMs":90000,"tone":"direct"}','trash-create-key-0001')::text,true);
reset role;
update public.project_revisions set settings='{"voice":"male","captions":true,"theme":"topic"}' where project_id=(current_setting('test.source')::jsonb->>'id')::uuid;
set local role authenticated;
select throws_ok($$select private.transition_idea_project(null,'{}','trash-test-key-0001',true)$$,'42501',null,'Private helper inaccessible');
select throws_ok($$select public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{}','trash-test-key-0001')$$,'P0001','VALIDATION_FAILED','Revision required');
select throws_ok($$select public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":"1"}','trash-test-key-0001')$$,'P0001','VALIDATION_FAILED','Typed revision required');
select throws_ok($$select public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1,"deleted_at":null}','trash-test-key-0001')$$,'P0001','VALIDATION_FAILED','Caller cannot set lifecycle fields');
select throws_ok($$select public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2147483647}','trash-test-key-0001')$$,'P0001','VALIDATION_FAILED','Revision overflow blocked');
select throws_ok($$select public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2}','trash-stale-key-0001')$$,'P0001','REVISION_CONFLICT','Stale delete blocked');
select set_config('request.jwt.claims','{"sub":"66666666-6666-4666-8666-666666666666","role":"authenticated"}',true);
select throws_ok($$select public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','trash-test-key-0001')$$,'P0001','RESOURCE_NOT_FOUND','Foreign delete concealed');
select set_config('request.jwt.claims','{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated"}',true);
select set_config('test.trashed',public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','trash-test-key-0001')::text,true);
select is(current_setting('test.trashed')::jsonb->>'status','trashed','Deletion acknowledged as Trash');
select is(current_setting('test.trashed')::jsonb->>'revision','2','Delete advances concurrency version');
select is(public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','trash-test-key-0001'),current_setting('test.trashed')::jsonb,'Delete retry is idempotent');
select is((select count(*)::integer from public.projects),0,'Trashed project hidden by RLS');
select is((select count(*)::integer from public.project_revisions),0,'Trashed history hidden by RLS');
select is(public.list_idea_projects(),'[]'::jsonb,'Active library hides Trash');
select is(jsonb_array_length(public.list_trashed_idea_projects()),1,'Trash summary includes own project');
select is(public.list_trashed_idea_projects()->0->>'title','Keep me','Trash title preserved');
select ok(not ((public.list_trashed_idea_projects()->0)?'brief'),'Trash summaries omit creative body');
select throws_ok($$select public.get_idea_project((current_setting('test.source')::jsonb->>'id')::uuid)$$,'P0001','RESOURCE_NOT_FOUND','Normal detail hidden');
select throws_ok($$select public.save_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1,"brief":"Old tab"}','trash-save-stale-001')$$,'P0001','RESOURCE_NOT_FOUND','Pending saves cannot edit Trash');
select throws_ok($$select public.duplicate_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2}','trash-duplicate-001')$$,'P0001','RESOURCE_NOT_FOUND','Trash cannot be copied');
select throws_ok($$delete from public.projects where id=(current_setting('test.source')::jsonb->>'id')::uuid$$,'42501',null,'Direct hard delete denied');
select set_config('request.jwt.claims','{"sub":"66666666-6666-4666-8666-666666666666","role":"authenticated"}',true);
select is(public.list_trashed_idea_projects(),'[]'::jsonb,'Foreign Trash invisible');
select throws_ok($$select public.restore_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2}','restore-test-key-001')$$,'P0001','RESOURCE_NOT_FOUND','Foreign restore concealed');
select set_config('request.jwt.claims','{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated"}',true);
select throws_ok($$select public.restore_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','restore-stale-key-01')$$,'P0001','REVISION_CONFLICT','Stale restore blocked');
select set_config('test.restored',public.restore_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2}','restore-test-key-001')::text,true);
select is(current_setting('test.restored')::jsonb->>'revision','3','Restore advances concurrency version');
select is(current_setting('test.restored')::jsonb->>'brief','Saved idea','Saved idea restored');
select is(current_setting('test.restored')::jsonb->>'referenceText','Saved notes','Saved notes restored');
select is(current_setting('test.restored')::jsonb->>'targetDurationMs','90000','Duration restored');
select is(current_setting('test.restored')::jsonb->'settings','{"voice":"male","captions":true,"theme":"topic"}'::jsonb,'Settings preserved');
select is((select count(*)::integer from public.project_revisions),3,'Original plus lifecycle snapshots preserved');
select is((select count(distinct content_hash)::integer from public.project_revisions),1,'Lifecycle does not change creative content hash');
select is(public.list_trashed_idea_projects(),'[]'::jsonb,'Restored draft leaves Trash');
select throws_ok($$select public.save_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1,"brief":"Old tab"}','trash-old-after-001')$$,'P0001','REVISION_CONFLICT','Pre-delete autosave fenced after restore');
select is(public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":1}','trash-test-key-0001'),current_setting('test.trashed')::jsonb,'Old delete replay does not trash restored project');
select is(public.get_idea_project((current_setting('test.source')::jsonb->>'id')::uuid)->>'revision','3','Replay leaves current state unchanged');
select throws_ok($$select public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":3}','trash-test-key-0001')$$,'P0001','IDEMPOTENCY_CONFLICT','Delete key cannot change body');
select set_config('test.retrash',public.trash_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":3}','trash-second-key-001')::text,true);
select is(public.restore_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":2}','restore-test-key-001'),current_setting('test.restored')::jsonb,'Old restore replay returns original acknowledgement');
select is(public.list_trashed_idea_projects()->0->>'revision','4','Old restore replay does not restore retrash');
reset role;
update public.profiles set deletion_status='pending' where owner_id='55555555-5555-4555-8555-555555555555';
set local role authenticated;
select throws_ok($$select public.restore_idea_project((current_setting('test.source')::jsonb->>'id')::uuid,'{"expectedRevision":4}','restore-inactive-001')$$,'P0001','ACCOUNT_UNAVAILABLE','Inactive owner cannot restore');
select throws_ok($$select public.list_trashed_idea_projects()$$,'P0001','ACCOUNT_UNAVAILABLE','Inactive owner cannot list Trash');
select * from finish();
rollback;
